guided.solution:
import pandas as pd

sales = pd.DataFrame({
    "Region": ["North", "South", "North", "East", "South", "North", "East"],
    "Product": ["Pen", "Pen", "Book", "Book", "Book", "Pen", "Pen"],
    "Qty": [3, 1, 2, 5, 1, 4, 2],
    "Amount": [30.0, 10.0, 40.0, 100.0, 20.0, 40.0, 20.0],
})

def total(region, min_qty):
    mask = (sales["Region"].str.lower() == region.lower()) & (sales["Qty"] >= min_qty)
    return sales.loc[mask, "Amount"].sum()

print(total("north", 2))
print(total("EAST", 1))
print(total("West", 1))
